bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,pw=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:pw,max:1,connectionTimeoutMillis:5000});
try{
 const q=await pool.query("SELECT a.delivery_key AS old_key,a.listing_id,a.revision AS old_revision,a.topic_id,a.status AS old_status,a.free_message_ids AS old_free,a.paid_message_id AS old_paid,b.delivery_key AS new_key,b.status AS new_status,b.free_message_ids AS new_free,b.paid_message_id AS new_paid,l.revision AS current_revision,l.status AS listing_status FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id JOIN videobot_post_receipts b ON b.listing_id=a.listing_id AND b.revision=l.revision AND b.topic_id=a.topic_id WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
 if(q.rowCount!==1)process.exitCode=71;
 else{const r=q.rows[0];
 if(r.old_status!=='sent'||r.new_status!=='sent'||r.current_revision!==r.old_revision+1||r.old_paid!=4691||r.new_paid==4691||!Array.isArray(r.new_free)||r.new_free.length!==2||r.new_free.some(v=>[4689,4690,4691].includes(Number(v)))||!['published','paused'].includes(r.listing_status))process.exitCode=72;
 else if(!e.VIDEOBOT_VIDEO_SALE_THREAD_ID||Number(e.VIDEOBOT_VIDEO_SALE_THREAD_ID)!==Number(r.topic_id))process.exitCode=73;
 else{const t=await pool.query("SELECT count(*)::integer AS n FROM videobot_stars_ledger WHERE delivery_key=$1 AND kind='paid'",[r.old_key]);process.exitCode=t.rows[0].n>0?0:74;}
 }
}catch{process.exitCode=79}finally{await pool.end()}
JS
echo BUYER_SAFE_REPLACEMENT_SQL=PASS
